import {test} from 'node:test';import assert from 'node:assert/strict';import {mountExperience} from '../src/modules/bootstrap-controller.js';
function events(){const listeners=new Map();return {addEventListener(t,f){if(!listeners.has(t))listeners.set(t,new Set());listeners.get(t).add(f)},removeEventListener(t,f){listeners.get(t)?.delete(f)},emit(t){for(const f of listeners.get(t)??[])f()},count(){return [...listeners.values()].reduce((n,s)=>n+s.size,0)}}}
test('mount cleanup removes listeners and allows a fresh mount',()=>{const reduced={...events(),matches:true},host={...events(),innerWidth:1400,matchMedia:()=>reduced,requestIdleCallback:()=>1,cancelIdleCallback(){},clearTimeout(){},setTimeout},select={...events(),value:'auto'},canvas={hidden:true,hasAttribute:()=>true},poster={classList:{remove(){}},querySelector:()=>({...events(),complete:true})},status={textContent:''},doc={...events(),hidden:false,documentElement:{lang:'es'},querySelector:s=>({'#scene':canvas,'#scene-poster':poster,'#quality':select,'#quality-status':status}[s]??null)};const old=Object.getOwnPropertyDescriptor(globalThis,'navigator');Object.defineProperty(globalThis,'navigator',{configurable:true,value:{}});try{const dispose=mountExperience({doc,host});assert.equal(host.count(),1);assert.equal(select.count(),1);assert.equal(reduced.count(),1);dispose();dispose();assert.equal(host.count(),0);assert.equal(select.count(),0);assert.equal(reduced.count(),0);assert.equal(doc.count(),0);const again=mountExperience({doc,host});assert.equal(select.count(),1);again();assert.equal(select.count(),0);}finally{if(old)Object.defineProperty(globalThis,'navigator',old);else delete globalThis.navigator;}});
